package cpamp

import (
	"context"

	"encoding/json"
)

type TokenEvidence struct {
	Revision int64              `json:"revision"`
	SourceID string             `json:"source_id"`
	Details  SourceTokenDetails `json:"details"`
}

func (s *Service) enrichTokenEvidence(ctx context.Context, events []Event, book ComparisonPriceBook, through int64) error {
	if book.Policy != profileValuePolicy || through == 0 || len(events) == 0 {
		return nil
	}

	rows, err := s.db.QueryContext(ctx, `SELECT e.event_hash,e.revision,e.source_id,e.payload FROM analytics_token_evidence e JOIN analytics_events a ON a.event_hash=e.event_hash WHERE a.account=? AND e.revision<=? ORDER BY e.revision`, events[0].Account, through)
	if err != nil {
		return err
	}
	defer rows.Close()
	byHash := map[string]*TokenEvidence{}
	for rows.Next() {
		var hash, raw string
		var e TokenEvidence
		if err = rows.Scan(&hash, &e.Revision, &e.SourceID, &raw); err != nil {
			return err
		}
		if err = json.Unmarshal([]byte(raw), &e.Details); err != nil {
			return err
		}
		byHash[hash] = &e
	}
	if err = rows.Err(); err != nil {
		return err
	}
	for i := range events {
		events[i].TokenEvidence = byHash[events[i].Hash]
	}
	return nil
}
